cypress_script:
describe('Opening Links in New Windows', () => {
  it('should open a new window when clicking the link', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.get('a').contains('Click Here').click();
    cy.url().should('include', '/windows/new');
  });

  it('should not navigate away from the original page', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.get('a').contains('Click Here').click();
    cy.get('#content').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Opening Links in New Windows', () => {
  test('should open a new window when clicking the link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    await page.click('text=Click Here');
    await page.waitForURL('**/windows/new');
  });

  test('should not navigate away from the original page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    await page.click('text=Click Here');
    await expect(page.locator('#content')).toBeVisible();
  });
});
